/**
 * Unit tests for org.apache.commons.lang3.StringUtils.indexOfAny(String, String[])
 */
public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;











    @Test
    public void testIndexOfAny_MultipleMatches_FirstOneWins() {
        String[] searchStrs = {"c", "a", "b"};
        // 'a' is at 0, 'b' is at 1, 'c' is at 2. The method should return the minimum index.
        assertEquals("Should return the lowest index among all matches", 0, StringUtils.indexOfAny("abc", searchStrs));
    }












}

