/**
 * Unit tests for org.apache.commons.lang3.StringUtils.indexOfAny(String, String[])
 */
public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;













    @Test
    public void testIndexOfAny_MultipleMatches_LaterOneWins() {
        // In this case 'b' (index 1) appears before 'a' (index 2) in the search array, 
        // but the logic looks for the minimum index found in the source string.
        String[] searchStrs = {"z", "b", "a"};
        assertEquals("Should return the lowest index found in the string", 1, StringUtils.indexOfAny("abc", searchStrs));
    }










}

